-- LuaJIT 2.1 64-bit integer cdata (`LL`/`ULL`) semantics. Each line prints
-- a label and the result's type and text; errors print only "error", since
-- messages differ. `luajit_cint64.expected` is this script's output under
-- LuaJIT 2.1 (git 1788856981).
local function show(label, f)
  local ok, a, b = pcall(f)
  if ok then print(label, type(a), tostring(a), b ~= nil and tostring(b) or "")
  else print(label, "error") end
end
local function compiles(source)
  return loadstring(source) ~= nil
end
show("lit dec", function() return 3ll end)
show("lit ull", function() return 3ull end)
show("lit hex", function() return 0xffffffffffffffffull end)
show("lit hexll", function() return 0xffffffffffffffffll end)
show("lit upper", function() return 10ULL end)
show("lit mixed", function() return 10uLL end)
show("lit big", function() return 9223372036854775807ll end)
show("lit neg", function() return -5ll end)
show("add", function() return 1ll + 2 end)
show("add ull", function() return 1ll + 2ull end)
show("add num frac", function() return 1ll + 2.7 end)
show("add num neg frac", function() return 1ll + -2.7 end)
show("sub", function() return 0ull - 1 end)
show("mul wrap", function() return 0x7fffffffffffffffll * 2 end)
show("div", function() return 7ll / 2 end)
show("div neg", function() return -7ll / 2 end)
show("div0", function() return 7ll / 0 end)
show("div0u", function() return 7ull / 0 end)
show("mod", function() return -7ll % 3 end)
show("modu", function() return 7ull % 3 end)
show("mod0", function() return 7ll % 0 end)
show("pow", function() return 3ll ^ 4 end)
show("pow neg", function() return 2ll ^ -1 end)
show("unm", function() return -(5ull) end)
show("eq", function() return 1ll == 1 end)
show("eq2", function() return 1ll == 1ull end)
show("eq frac", function() return 1ll == 1.5 end)
show("eq str", function() return 1ll == "1" end)
show("lt", function() return 1ll < 2 end)
show("lt u", function() return -1ll < 1ull end)
show("le", function() return 2 <= 2ll end)
show("lt num frac", function() return 1ll < 1.5 end)
show("tonumber", function() return tonumber(0xffffffffffffffffull) end)
show("tonumber ll", function() return tonumber(-3ll) end)
show("tostring", function() return tostring(-3ll) end)
show("concat", function() return "x" .. 3ll end)
show("band", function() return bit.band(0x1ffffffffull, 0xffffffff) end)
show("band ll", function() return bit.band(-1ll, 0xff) end)
show("band num 64", function() return bit.band(0x123456789ll, 2^33+5) end)
show("bor mixed", function() return bit.bor(1ll, 2ull) end)
show("bxor", function() return bit.bxor(-1ll, 1) end)
show("rshift", function() return bit.rshift(-1ll, 60) end)
show("arshift", function() return bit.arshift(-16ll, 2) end)
show("arshift u", function() return bit.arshift(0x8000000000000000ull, 4) end)
show("lshift", function() return bit.lshift(1ll, 63) end)
show("lshift 64", function() return bit.lshift(1ll, 64) end)
show("rol", function() return bit.rol(0x8000000000000001ull, 1) end)
show("ror", function() return bit.ror(3ll, 1) end)
show("bnot", function() return bit.bnot(0ull) end)
show("bswap", function() return bit.bswap(0x0102030405060708ll) end)
show("tobit", function() return bit.tobit(0x1ffffffffll) end)
show("tohex", function() return bit.tohex(255ll) end)
show("tohex n", function() return bit.tohex(-1ll, -4) end)
show("shift count cdata", function() return bit.lshift(1, 3ll) end)
show("math.floor", function() return math.floor(3ll) end)
show("format d", function() return string.format("%d", 3ll) end)
show("format s", function() return string.format("%s", 3ll) end)
show("not", function() return not 0ll end)
show("len", function() return #(1ll) end)
show("index", function() return (1ll).x end)
show("tostr num", function() return tonumber("3ll") end)
show("loadstr", function() return loadstring("return 0x10ull")() end)
show("select", function() return select("#", 1ll) end)
show("math.max", function() return math.max(1ll, 2) end)
show("cmp u big", function() return 0xffffffffffffffffull > 1 end)
show("num to ll", function() return 1e20 * 1ll end)
show("nan to ll", function() return (0/0) * 1ll end)
show("neg num to ull", function() return -1 * 1ull end)
show("ll*ull", function() return -2ll * 3ull end)
show("ipairs key", function() local t = {10, 20} return t[2ll] end)
show("for", function() local n=0 for i = 1ll, 3 do n = n + 1 end return n end)
for _, n in ipairs{-1, -2.5, -0.5, 1e19, 1.9e19, 2^63, 2^64, -2^63, -1e19, 1e300, 1/0, 0/0, 9.2e18, 4294967296.5} do
  print(string.format("%.17g", n), tostring(n * 1ll), tostring(n * 1ull))
end
print(7ull / 0, 0ull/0, 7ll/0, -7ll/0, 0ll/0, (-9223372036854775807ll-1)/-1)
print(7ull % 0, 7ll % 0, (-9223372036854775807ll-1) % -1, -7ll % 0)
print(2ll^63, 2ll^64, 0ll^-1, 1ll^-5, (-1ll)^-3, (-1ll)^-4, 2ull^-1, 0ull^-1, 3ll^0, (-2ll)^3)
print(1ll < 0/0, 1ll == 0/0, 1ll <= 1/0, 0ull == -0.0, -1ll < 0ull)
print(bit.band(1ll, 0/0), bit.band(1ll, 2^32+3), bit.band(1ll, -1), bit.band(1ll, "3"), bit.band(0xffffffffffll, -1))
print(bit.band(2^32+3, 1ll), bit.bor(1e10, 0ll), bit.bor(-1, 0ull), bit.bor(2^63, 0ull), bit.bor(1ll, 2^63), bit.bor(1ull, 2^63))
print(bit.lshift(1, 33ll), bit.rshift(1ll, 3ull), bit.arshift(-8ull, 1), bit.rol(1ull, -1), bit.lshift(1ll, 2^32+1))
print(bit.tobit(-1ull), bit.tohex(2^40+5ll), bit.tohex(-1ll, 8), bit.tohex(0xabcll, -3), bit.tohex(255ll, 2ll), bit.tohex(1ll, 20))
print(bit.bnot(5ll), bit.bswap(1ull), bit.bnot(-1ll), bit.band(-1ll, -1, 7ull))
print(string.format("%5s|%-6d|%x|%X|%o|%d|%5.2d", 3ll, 4ll, 255ull, 255ll, 8ll, 0xffffffffffffffffull, 3ll))
print(tonumber(1ll, 10), tonumber(-1ull, 10), math.huge * 0ll)
for _, s in ipairs{"1llu", "1LLU", "0x10Ull", "10lL", "0xfull", "9223372036854775808ll", "0x8000000000000000ll", "00012ll", "18446744073709551615ll"} do
  print(s, tostring(loadstring("return " .. s)()))
end
for _, s in ipairs{"1e3ll", "0x1p4ll", "1.ll", "1lul", "1u", "1l", "1ullx", "1ULLL", "0xffffffffffffffffffll", "18446744073709551616ull"} do
  print(s, compiles("return " .. s))
end
print(loadstring(string.dump(function() return 5ull, -3ll, 0x8000000000000000ull end))())
